from pathlib import Path


def tokens(path="tokens.txt"):
    return [line.strip() for line in Path(path).read_text().splitlines() if line.strip()]


def load(path="replica.toml"):
    settings = {}
    for raw in Path(path).read_text().splitlines():
        line = raw.strip()
        if not line or line[0] in "#":
            continue
        key, val = line.split("=", 1)
        settings[key.strip()] = val.strip().strip('"')
    valid = tokens()
    catalog_policy = settings["catalog_reads"]
    if catalog_policy not in valid:
        raise SystemExit("unknown policy")
    session_policy = settings["session_writes"]
    if session_policy not in valid:
        raise SystemExit("unknown policy")
    return settings
